// ------------------------
// Environment
// ------------------------
function cleanEnvText(value, fallback, maxChars = 120) {
  const cleaned = String(value ?? "")
    .replace(/[\u0000-\u001F\u007F]/g, " ")
    .replace(/[<>&"'`=]/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, maxChars)
    .trim();
  return cleaned || fallback;
}

function cleanEnvEmail(value, fallback) {
  const cleaned = cleanEnvText(value, "", 254).replace(/\s+/g, "");
  if (/^[A-Za-z0-9.!#$%*+/=?^_{|}~-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+$/.test(cleaned)) {
    return cleaned;
  }
  return fallback;
}

function cleanEnvOrigin(value, fallback) {
  const raw = String(value ?? "")
    .replace(/[\u0000-\u001F\u007F\s]/g, "")
    .replace(/[<>"'`]/g, "")
    .trim()
    .replace(/\/+$/, "");
  try {
    const parsed = new URL(raw);
    if (!["http:", "https:"].includes(parsed.protocol)) return fallback;
    return parsed.origin.replace(/\/$/, "");
  } catch {}
  return fallback;
}

function cleanOAuthUrl(value) {
  const raw = String(value ?? "")
    .replace(/[\u0000-\u001F\u007F\s]/g, "")
    .replace(/[<>"'`]/g, "")
    .trim();
  if (!raw) return "";
  try {
    const parsed = new URL(raw);
    if (!["http:", "https:"].includes(parsed.protocol)) return "";
    if (parsed.username || parsed.password || parsed.search || parsed.hash) return "";
    const localHttp = parsed.protocol === "http:" && ["localhost", "127.0.0.1", "::1"].includes(parsed.hostname);
    if (parsed.protocol !== "https:" && !localHttp) return "";
    const normalized = parsed.toString();
    return raw.endsWith("/") ? normalized : normalized.replace(/\/$/, "");
  } catch {
    return "";
  }
}

function cleanDemoVideoUrl(value) {
  const raw = String(value ?? "")
    .replace(/[\u0000-\u001F\u007F\s]/g, "")
    .replace(/[<>"'`]/g, "")
    .trim();
  if (!raw) return "";
  try {
    const parsed = new URL(raw);
    const hostname = parsed.hostname.toLowerCase();
    if (parsed.protocol !== "https:" || parsed.username || parsed.password) return "";
    if (!["youtube.com", "www.youtube.com", "youtu.be"].includes(hostname)) return "";
    return parsed.toString();
  } catch {
    return "";
  }
}

function youtubeNoCookieEmbedUrl(value) {
  const safeUrl = cleanDemoVideoUrl(value);
  if (!safeUrl) return "";
  try {
    const parsed = new URL(safeUrl);
    const hostname = parsed.hostname.toLowerCase();
    let videoId = "";
    if (hostname === "youtu.be") {
      videoId = parsed.pathname.split("/").filter(Boolean)[0] || "";
    } else if (parsed.pathname === "/watch") {
      videoId = parsed.searchParams.get("v") || "";
    } else {
      const pathMatch = parsed.pathname.match(/^\/(?:embed|shorts|live)\/([^/]+)$/);
      videoId = pathMatch?.[1] || "";
    }
    if (!/^[A-Za-z0-9_-]{6,64}$/.test(videoId)) return "";
    return `https://www.youtube-nocookie.com/embed/${videoId}?rel=0&playsinline=1`;
  } catch {
    return "";
  }
}

function renderEnvironmentDetected(env = process.env) {
  return Object.prototype.hasOwnProperty.call(env, "RENDER")
    || Object.prototype.hasOwnProperty.call(env, "RENDER_GIT_COMMIT")
    || Object.prototype.hasOwnProperty.call(env, "RENDER_GIT_BRANCH")
    || Object.prototype.hasOwnProperty.call(env, "RENDER_SERVICE_NAME");
}

function cleanDeploymentCommitSha(value) {
  const sha = String(value || "").trim().toLowerCase();
  return /^(?:[a-f0-9]{40}|[a-f0-9]{64})$/.test(sha) ? sha : "";
}

function buildRenderDeploymentMetadata(env = process.env) {
  if (!renderEnvironmentDetected(env)) return {};

  return { deploymentProvider: "render" };
}

function buildDeploymentEvidencePayload(env = process.env) {
  const deployedSha = renderEnvironmentDetected(env)
    ? cleanDeploymentCommitSha(env.RENDER_GIT_COMMIT)
    : "";
  if (!deployedSha) {
    return {
      ok: false,
      schemaVersion: "turnfeed-deployment-evidence-v1",
      code: "deployment_sha_unavailable",
    };
  }
  return {
    ok: true,
    schemaVersion: "turnfeed-deployment-evidence-v1",
    deployedSha,
  };
}

