const extractPathname = (maybeUrlOrPath) => {
  try {
    const u = new URL(maybeUrlOrPath);
    return u.pathname;
  } catch {
    if (typeof maybeUrlOrPath !== "string") return null;
    if (!maybeUrlOrPath.startsWith("/")) return `/${maybeUrlOrPath}`;
    return maybeUrlOrPath;
  }
};

const normalizePath = (p) => {
  const s = typeof p === "string" ? p : "";
  const noQuery = s.split("?")[0].split("#")[0];
  const withoutTrailing = noQuery !== "/" ? noQuery.replace(/\/+$/, "") : noQuery;
  return withoutTrailing || "/";
};

const OPENAI_DOMAIN_VERIFICATION_PATH = normalizePath(
  extractPathname(OPENAI_DOMAIN_VERIFICATION_PATH_RAW) ?? CANONICAL_OPENAI_DOMAIN_VERIFICATION_PATH
);

function firstHeaderValue(value) {
  if (Array.isArray(value)) return String(value[0] ?? "").trim();
  return String(value ?? "")
    .split(",")[0]
    .trim();
}

function normalizePublicOriginValue(value) {
  const raw = String(value ?? "").trim().replace(/\/+$/, "");
  if (!raw || /[\u0000-\u001F\u007F\s"'`;\\]/.test(raw)) return "";
  try {
    const parsed = new URL(raw);
    if (!["http:", "https:"].includes(parsed.protocol)) return "";
    if (!parsed.hostname) return "";
    return parsed.origin;
  } catch {
    return "";
  }
}

function knownPublicOrigins() {
  return new Set(
    [PUBLIC_ORIGIN, "https://turnfeedapp.com", "https://www.turnfeedapp.com"]
      .map(normalizePublicOriginValue)
      .filter(Boolean)
  );
}

function isAllowedPublicOrigin(origin) {
  const normalized = normalizePublicOriginValue(origin);
  if (!normalized) return false;
  try {
    const parsed = new URL(normalized);
    if (isLocalHostname(parsed.hostname)) {
      return normalized === normalizePublicOriginValue(PUBLIC_ORIGIN);
    }
    if (parsed.protocol !== "https:") return false;
    return knownPublicOrigins().has(normalized);
  } catch {
    return false;
  }
}

function strictTransportSecurityHeader(origin = PUBLIC_ORIGIN) {
  const normalized = normalizePublicOriginValue(origin);
  if (!normalized) return "";
  try {
    const parsed = new URL(normalized);
    if (parsed.protocol !== "https:" || isLocalHostname(parsed.hostname)) return "";
    return "max-age=31536000";
  } catch {
    return "";
  }
}

function getRequestOrigin(req) {
  const forwardedHost = firstHeaderValue(req.headers["x-forwarded-host"]);
  const host = forwardedHost || firstHeaderValue(req.headers.host);
  if (!host) return "";
  const hostname = host.split(":")[0];
  const proto =
    firstHeaderValue(req.headers["x-forwarded-proto"]) ||
    (!isLocalHostname(hostname) ? "https" : req.socket?.encrypted ? "https" : "http");
  return `${proto}://${host}`.replace(/\/$/, "");
}

function isLegacyDeploymentOrRequest(req) {
  return (
    TURNFEED_LEGACY_REDIRECT_ONLY ||
    normalizePublicOriginValue(getRequestOrigin(req)) === TURNFEED_LEGACY_ORIGIN
  );
}

function resolvePublicOrigin(req) {
  const fallback = normalizePublicOriginValue(PUBLIC_ORIGIN) || PUBLIC_ORIGIN;
  const requestOrigin = normalizePublicOriginValue(getRequestOrigin(req));
  if (requestOrigin && isAllowedPublicOrigin(requestOrigin)) return requestOrigin;
  return fallback;
}

function resolveSupportEmail(publicOrigin = PUBLIC_ORIGIN) {
  const configured = String(SUPPORT_EMAIL || "").trim();
  if (configured && configured.toLowerCase() !== LEGACY_SUPPORT_EMAIL.toLowerCase()) return configured;
  try {
    const { hostname } = new URL(publicOrigin);
    if (/^(.+\.)?turnfeedapp\.com$/i.test(hostname)) return FALLBACK_SUPPORT_EMAIL;
  } catch {}
  return FALLBACK_SUPPORT_EMAIL;
}

function cloneSecuritySchemes(securitySchemes = MCP_NOAUTH_SECURITY_SCHEMES) {
  return securitySchemes.map((scheme) => ({
    ...scheme,
    ...(Array.isArray(scheme?.scopes) ? { scopes: [...scheme.scopes] } : {}),
  }));
}

function isMcpEndpointPath(path) {
  return MCP_ENDPOINT_PATHS.includes(path);
}

function isOAuthProtectedResourcePath(path) {
  return path === OAUTH_PROTECTED_RESOURCE_PATH || OAUTH_PROTECTED_RESOURCE_MCP_PATHS.includes(path);
}

function mcpProtectedResourceMetadata() {
  return JSON.stringify({
    resource: TURNFEED_CANONICAL_MCP_RESOURCE,
    authorization_servers: [TURNFEED_OAUTH_ISSUER],
    scopes_supported: [...TURNFEED_SUPPORTED_OAUTH_SCOPES],
    resource_documentation: `${PUBLIC_ORIGIN}${MCP_INFO_PATH}`,
  });
}

function setMcpConnectionHeaders(res, origin = PUBLIC_ORIGIN) {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Expose-Headers", "Mcp-Session-Id, WWW-Authenticate");
  res.setHeader("Allow", "POST, DELETE, OPTIONS, HEAD");
  res.setHeader("Cache-Control", "no-store");
  res.setHeader("X-Robots-Tag", "noindex, nofollow");
  res.setHeader("Link", `<${origin}${MCP_INFO_PATH}>; rel=\"describedby\"; type=\"text/html\"`);
}

function oauthChallengeValue({ scopes = [], error = "invalid_token", description = "Authentication required." } = {}) {
  const safeScopes = [...new Set(scopes.map((scope) => String(scope || "").trim()).filter(Boolean))];
  const cleanError = String(error || "invalid_token").replace(/[^a-z_]/gi, "_").slice(0, 64) || "invalid_token";
  const cleanDescription = String(description || "Authentication required.")
    .replace(/[\u0000-\u001F\u007F"\\]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 240);
  return [
    `Bearer resource_metadata="${TURNFEED_OAUTH_RESOURCE_METADATA_URL}"`,
    ...(safeScopes.length ? [`scope="${safeScopes.join(" ")}"`] : []),
    `error="${cleanError}"`,
    `error_description="${cleanDescription}"`,
  ].join(", ");
}

function mcpAuthorizationError(ctx, requiredScopes = []) {
  const availableScopes = new Set(Array.isArray(ctx?.authInfo?.scopes) ? ctx.authInfo.scopes : []);
  const missingScopes = requiredScopes.filter((scope) => !availableScopes.has(scope));
  const hasVerifiedIdentity = Boolean(authenticatedOAuthIdentity(ctx));
  const error = hasVerifiedIdentity ? "insufficient_scope" : "invalid_token";
  const message = hasVerifiedIdentity
    ? "Turnfeed does not have the permission needed for this action. Reconnect Turnfeed, approve the access ChatGPT shows, and try again."
    : "Connect Turnfeed to continue with this action.";
  const challenge = oauthChallengeValue({
    scopes: missingScopes.length ? missingScopes : requiredScopes,
    error,
    description: message,
  });
  return {
    content: [{ type: "text", text: message }],
    isError: true,
    _meta: { "mcp/www_authenticate": [challenge] },
  };
}

function authenticatedOAuthIdentity(ctx) {
  const extra = ctx?.authInfo?.extra;
  const subject = typeof extra?.sub === "string" ? extra.sub.trim() : "";
  const issuer = typeof extra?.issuer === "string" ? extra.issuer.trim() : "";
  if (!subject || !issuer || issuer !== TURNFEED_OAUTH_ISSUER) return null;
  return { issuer, subject };
}

function anonymousMcpToolContext(ctx) {
  if (!ctx || typeof ctx !== "object" || !ctx.authInfo) return ctx;
  return { ...ctx, authInfo: undefined };
}

function publishedV2McpToolContext(ctx) {
  const source = ctx && typeof ctx === "object" ? ctx : {};
  return {
    ...source,
    authInfo: undefined,
    [PUBLISHED_V2_MCP_CONTEXT]: true,
  };
}

function isPublishedV2McpToolContext(ctx) {
  return ctx?.[PUBLISHED_V2_MCP_CONTEXT] === true;
}

function oauthUserIdForIdentity(identity) {
  if (!identity || !TURNFEED_IDENTITY_PEPPER) return "";
  return createHmac("sha256", TURNFEED_IDENTITY_PEPPER)
    .update("turnfeed-oauth-user-v1|")
    .update(identity.issuer)
    .update("|")
    .update(identity.subject)
    .digest("hex")
    .slice(0, 40);
}

function authenticatedOAuthUserId(ctx) {
  return oauthUserIdForIdentity(authenticatedOAuthIdentity(ctx));
}

function oauthScopesFromPayload(payload = {}) {
  // Only the delegated OAuth `scope` claim grants Turnfeed authority.
  // Provider-specific role/permission claims must never expand what the user
  // requested and consented to for this access token.
  const values = typeof payload.scope === "string" ? payload.scope.split(/\s+/) : [];
  return [...new Set(values.map((value) => String(value || "").trim()).filter(Boolean))];
}

async function verifyMcpBearerRequest(req) {
  const rawAuthorization = Array.isArray(req?.headers?.authorization)
    ? String(req.headers.authorization[0] || "").trim()
    : String(req?.headers?.authorization || "").trim();
  if (!rawAuthorization) return null;
  const match = rawAuthorization.match(/^Bearer\s+([^\s]+)$/i);
  if (!match || match[1].length > 16_384) {
    const error = new Error("Malformed bearer token.");
    error.code = "invalid_token";
    throw error;
  }
  if (!TURNFEED_OAUTH_CONFIGURED || !TURNFEED_REMOTE_JWKS) {
    const error = new Error("OAuth is not configured.");
    error.code = "invalid_token";
    throw error;
  }
  try {
    const token = match[1];
    const { payload } = await jwtVerify(token, TURNFEED_REMOTE_JWKS, {
      issuer: TURNFEED_OAUTH_ISSUER,
      audience: TURNFEED_OAUTH_AUDIENCE,
      algorithms: ["RS256"],
      clockTolerance: 5,
      requiredClaims: ["iss", "aud", "sub", "exp"],
    });
    const rawSubject = typeof payload.sub === "string" ? payload.sub : "";
    const subject = rawSubject.trim();
    if (!subject || subject !== rawSubject || subject.length > 512) {
      throw new Error("Token subject is invalid.");
    }
    const clientId = String(payload.azp || payload.client_id || "chatgpt").trim().slice(0, 240) || "chatgpt";
    return {
      token,
      clientId,
      scopes: oauthScopesFromPayload(payload),
      ...(Number.isFinite(payload.exp) ? { expiresAt: Number(payload.exp) } : {}),
      resource: new URL(TURNFEED_OAUTH_AUDIENCE),
      extra: {
        issuer: TURNFEED_OAUTH_ISSUER,
        sub: subject,
      },
    };
  } catch (cause) {
    const error = new Error("Invalid or expired bearer token.", { cause });
    error.code = "invalid_token";
    throw error;
  }
}

function sendMcpUnauthorized(res, {
  description = "Turnfeed could not verify this connection. Connect or reconnect Turnfeed, then try again.",
} = {}) {
  const body = JSON.stringify({ ok: false, error: "invalid_token", message: description });
  res.writeHead(401, {
    "Content-Type": "application/json; charset=utf-8",
    "WWW-Authenticate": oauthChallengeValue({ error: "invalid_token", description }),
    "Content-Length": String(Buffer.byteLength(body)),
  });
  res.end(body);
}

function withTopLevelToolSecuritySchemes(message) {
  const decorate = (entry) => {
    if (!entry || typeof entry !== "object" || !Array.isArray(entry?.result?.tools)) return entry;
    return {
      ...entry,
      result: {
        ...entry.result,
        tools: entry.result.tools.map((tool) => {
          const securitySchemes = tool?._meta?.securitySchemes;
          return Array.isArray(securitySchemes) && securitySchemes.length
            ? { ...tool, securitySchemes: cloneSecuritySchemes(securitySchemes) }
            : tool;
        }),
      },
    };
  };
  return Array.isArray(message) ? message.map(decorate) : decorate(message);
}

function withPublishedV2Catalog(message) {
  const decorate = (entry) => {
    if (!entry || typeof entry !== "object" || !entry.result || typeof entry.result !== "object") {
      return entry;
    }
    if (Array.isArray(entry.result.tools)) {
      return {
        ...entry,
        result: {
          ...entry.result,
          tools: PUBLISHED_V2_CATALOG.tools,
        },
      };
    }
    if (Array.isArray(entry.result.resources)) {
      return {
        ...entry,
        result: {
          ...entry.result,
          resources: PUBLISHED_V2_CATALOG.resources,
        },
      };
    }
    return entry;
  };
  return Array.isArray(message) ? message.map(decorate) : decorate(message);
}

function isBrowserMcpInfoRequest(req) {
  const accept = String(req?.headers?.accept ?? "").toLowerCase();
  if (!accept.includes("text/html")) return false;
  if (accept.includes("text/event-stream") || accept.includes("application/json")) return false;
  if (req?.headers?.["mcp-session-id"]) return false;
  return true;
}

// ------------------------
// Persistence (Render-safe)
