function resolveDataDir(env = process.env, candidateDirs = null) {
  const projectDataDir = join(__dirname, "data");
  const safeTestRun = readEnv(env, "TURNFEED_TEST_SAFE") === "1";
  const candidates = Array.isArray(candidateDirs)
    ? candidateDirs
    : safeTestRun || process.platform === "win32"
      ? [projectDataDir]
      : [join("/var", "data", "turnfeed"), projectDataDir];
  for (const dir of candidates) {
    let alreadyPresent = false;
    try {
      lstatSync(dir);
      alreadyPresent = true;
    } catch (err) {
      if (err?.code !== "ENOENT") throw err;
    }
    try {
      mkdirSync(dir, { recursive: true, mode: 0o700 });
    } catch (err) {
      if (alreadyPresent || dir === candidates.at(-1)) throw err;
      continue;
    }
    if (!lstatSync(dir).isDirectory()) throw new Error("Data path must be a directory, not a symlink");
    if (process.platform !== "win32") {
      chmodSync(dir, 0o700);
      if (lstatSync(dir).mode & 0o077) throw new Error("Data directory must be owner-only");
    }
    return dir;
  }
  throw new Error("Turnfeed could not secure a private data directory");
}
const DATA_DIR = resolveDataDir();
const STORE_PATH = join(DATA_DIR, "store.json");
const ADMIN_KEY_PATH = join(DATA_DIR, "admin.key");
function protectExistingDataFile(path) {
  let stat;
  try {
    stat = lstatSync(path);
  } catch (err) {
    if (err?.code === "ENOENT") return;
    throw err;
  }
  if (!stat.isFile() || stat.nlink !== 1) throw new Error("Turnfeed data must be a regular unlinked file");
  if (process.platform !== "win32") {
    chmodSync(path, 0o600);
    if (lstatSync(path).mode & 0o077) throw new Error("Turnfeed data file must be owner-only");
  }
}
for (const name of readdirSync(DATA_DIR)) {
  if (name.startsWith("store.json") || name.startsWith("admin.key")) {
    protectExistingDataFile(join(DATA_DIR, name));
  }
}
