function resolveAdminSessionValidityMs(env = process.env) {
  if (!TURNFEED_TEST_NOAUTH_ENABLED) return ADMIN_SESSION_MAX_AGE_MS;
  const raw = String(env?.TURNFEED_TEST_ADMIN_SESSION_MAX_AGE_MS ?? "").trim();
  if (!/^[1-9][0-9]*$/.test(raw)) return ADMIN_SESSION_MAX_AGE_MS;
  const value = Number(raw);
  if (!Number.isSafeInteger(value) || value < 100 || value > ADMIN_SESSION_MAX_AGE_MS) {
    return ADMIN_SESSION_MAX_AGE_MS;
  }
  return value;
}

