  const groupName = typeof result?.groupName === "string" ? result.groupName : "";
  const groupVisibility = result?.groupVisibility === "private" ? "private" : result?.groupVisibility === "public" ? "public" : "";
  const reusedExistingGroup = Boolean(result?.reusedExistingGroup);
