function replyPostedThreadResult(result, userId, { action = "" } = {}) {
  const focusPostId = typeof result?.postId === "string" ? result.postId.trim() : "";
  const replyId = typeof result?.replyId === "string" ? result.replyId.trim() : "";
  const focusReplyId = typeof result?.focusReplyId === "string" && result.focusReplyId.trim()
    ? result.focusReplyId.trim()
    : replyId;
  if (result?.needsConfirmation) {
    return replyWithActionResult(result, actionSyncExtraForUserId(userId, {
      action,
      entryMode: "feed",
      entrySummary: "Public reply prepared; confirmation required.",
      cardEntrySummary: "Public reply prepared; confirmation required.",
      resolvedTargetKind: "feed",
      resolvedTargetLabel: "Social feed",
      resolvedBy: action || "reply-confirmation-required",
      focusPostPreview: null,
      focusPostId: "",
      postId: "",
      replyId: "",
      focusReplyId: "",
      agentProtocol: buildTurnfeedAgentProtocolBrief(),
      nextActionHint: "",
      nextChatPrompts: [],
    }));
  }
  if (!result?.ok) {
    const message = typeof result?.message === "string" && result.message.trim()
      ? result.message.trim()
      : "Reply not sent.";
    return replyWithActionResult({ ...result, ok: false, message }, actionSyncExtraForUserId(userId, {
      action,
      entryMode: "feed",
      entrySummary: "Reply not sent.",
      cardEntrySummary: "Reply not sent.",
      resolvedTargetKind: "feed",
      resolvedTargetLabel: "Social feed",
      resolvedBy: action || "reply-not-sent",
      focusPostPreview: null,
      focusPostId: "",
      postId: "",
      replyId: "",
      focusReplyId: "",
      agentProtocol: buildTurnfeedAgentProtocolBrief(),
      nextActionHint: "",
      nextChatPrompts: [],
    }));
  }
  return replyWithActionResult({ ...result, ok: true, message: "Sent your reply." }, actionSyncExtraForUserId(userId, {
    action,
    entryMode: focusPostId ? "thread" : "feed",
    entrySummary: "Sent your reply.",
    cardEntrySummary: "Sent your reply.",
    resolvedTargetKind: focusPostId ? "thread" : "feed",
    resolvedTargetLabel: focusPostId
      ? buildOpenSocialResolvedLabel({ viewerUserId: userId, resolvedTargetKind: "thread", focusPostId })
      : "Social feed",
    resolvedBy: action || "reply-sent",
    focusPostPreview: focusPostId ? buildOpenSocialFocusPostPreview(userId, focusPostId) : null,
    focusPostId,
    postId: focusPostId,
    replyId,
    focusReplyId,
    agentProtocol: buildTurnfeedAgentProtocolBrief(),
    nextActionHint: focusPostId ? TURNFEED_REPLY_NEXT_ACTION_HINT : "",
    nextChatPrompts: focusPostId ? ["Read this thread.", "Show this thread here."] : [],
  }));
}

